<?php declare(strict_types=1); require __DIR__.'/admin-empresa-action-common.php'; admin_empresa_post(); [$app,$session]=admin_empresa_context(); try{$id=filter_var($_POST['empresa_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!is_int($id))throw new InvalidArgumentException('Empresa inválida.');$app->companyAdmin()->status($id,(string)($_POST['status']??''));$session->flash('success','Status da empresa atualizado.');}catch(InvalidArgumentException $e){$session->flash('danger',$e->getMessage());}catch(Throwable $e){error_log('Company status failed: '.get_class($e));$session->flash('danger','Não foi possível alterar o status.');}admin_empresa_redirect($app);
